const CACHE='frame-camera-v7';
const SHELL=['./i18n.js?v=7','./translations.js?v=7','./native-bridge.js?v=7','./','./index.html','./style.css?v=7','./app.js?v=7','./camera-session.js?v=7','./coach.js?v=7','./metric-guide.js?v=7','./photo-analysis.js?v=7','./manifest.webmanifest?v=7','./assets/demo-portrait.jpg','./assets/icon.svg?v=7','./assets/icon-192.png?v=7','./assets/icon-512.png?v=7'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('frame-camera-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin||event.request.url.includes('qa-camera'))return;event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok){try{const cache=await caches.open(CACHE);await cache.put(event.request,response.clone());}catch{}}return response;}catch{return await caches.match(event.request)||Response.error();}})());});
